type Shape = { kind: "circle"; r: number } | { kind: "square"; a: number }

function area(shape: Shape): number {
    switch (shape.kind) {
        case "circle":
            return Math.PI * shape.r ** 2
        case "square":
            return shape.a ** 2
        default: {
            const exhaustive: never = shape
            return exhaustive
        }
    }
}

